fn trim(value: &str, field: &str, max: usize) -> Result<String, String> {
    let value = value.trim();
    if value.is_empty() { return Err(format!("{field} é obrigatório.")); }
    if value.chars().count() > max { return Err(format!("{field} aceita no máximo {max} caracteres.")); }
    Ok(value.to_owned())
}
fn with_db<T>(state: &AppState, f: impl FnOnce(&Connection) -> rusqlite::Result<T>) -> Result<T, (StatusCode, Json<ErrorBody>)> {
    let db = state.db.lock().map_err(|_| error(StatusCode::INTERNAL_SERVER_ERROR, "Banco indisponível."))?;
    f(&db).map_err(|e| error(StatusCode::INTERNAL_SERVER_ERROR, format!("Erro no banco: {e}")))
}
fn folder_exists(db: &Connection, id: i64) -> rusqlite::Result<bool> { db.query_row("SELECT EXISTS(SELECT 1 FROM folders WHERE id = ?1)", [id], |row| row.get(0)) }
fn folder_is_descendant(db: &Connection, id: i64, candidate: i64) -> rusqlite::Result<bool> { db.query_row("WITH RECURSIVE descendants(id) AS (SELECT id FROM folders WHERE parent_id=?1 UNION ALL SELECT f.id FROM folders f JOIN descendants d ON f.parent_id=d.id) SELECT EXISTS(SELECT 1 FROM descendants WHERE id=?2)",params![id,candidate],|row|row.get(0)) }
fn validate_example(input:&CreateDatasetExample)->Result<(),String>{if input.id.trim().is_empty(){return Err("id é obrigatório.".into())}let _:Value=serde_json::from_str(&input.state).map_err(|_|"state deve conter JSON válido.".to_string())?;let questions:Value=serde_json::from_str(&input.questions).map_err(|_|"questions deve conter JSON válido.".to_string())?;let gold:Value=serde_json::from_str(&input.gold).map_err(|_|"gold deve conter JSON válido.".to_string())?;let q=questions.as_object().ok_or("questions deve ser objeto JSON.")?;let g=gold.as_object().ok_or("gold deve ser objeto JSON.")?;for(key,value)in q{let question=value.as_object().ok_or_else(||format!("questions.{key} deve ser objeto."))?;let kind=question.get("type").and_then(Value::as_str).ok_or_else(||format!("questions.{key}.type é obrigatório."))?;let answer=g.get(key).ok_or_else(||format!("gold.{key} está ausente."))?;match kind{"noul"=>{if !answer.is_boolean(){return Err(format!("gold.{key} deve ser booleano para noul."))}},"choice"=>{let labels=question.get("labels").or_else(||question.get("choices")).and_then(Value::as_array).ok_or_else(||format!("questions.{key}.labels é obrigatório para choice."))?;let selected=answer.as_str().ok_or_else(||format!("gold.{key} deve ser um label para choice."))?;if !labels.iter().any(|v|v.as_str()==Some(selected)){return Err(format!("gold.{key} não pertence aos labels declarados."))}},"score"=>{if question.get("criteria").and_then(Value::as_array).map_or(true,|v|v.is_empty()){return Err(format!("questions.{key}.criteria é obrigatório para score."))}let score=answer.as_f64().or_else(||answer.get("score").and_then(Value::as_f64)).ok_or_else(||format!("gold.{key}.score deve ser numérico."))?;if !(0.0..=1.0).contains(&score){return Err(format!("gold.{key}.score deve estar entre 0 e 1."))}if let Some(p)=answer.get("probabilities").and_then(Value::as_object){let sum:f64=p.values().map(|v|v.as_f64().unwrap_or(-1.0)).sum();if p.values().any(|v|v.as_f64().map_or(true,|x|!(0.0..=1.0).contains(&x)))||(sum-1.0).abs()>0.001{return Err(format!("gold.{key}.probabilities deve somar 1."))}}},_=>return Err(format!("questions.{key}.type não é reconhecido pelo LAYA."))}}for key in g.keys(){if !q.contains_key(key){return Err(format!("gold.{key} não possui pergunta correspondente."))}}Ok(())}
fn example_from_json(value:Value)->Result<CreateDatasetExample,String>{let object=value.as_object().ok_or("A linha deve ser um objeto JSON.")?;let id=object.get("id").and_then(Value::as_str).ok_or("id é obrigatório.")?.to_string();let state=object.get("state").ok_or("state é obrigatório.")?.to_string();let questions=object.get("questions").ok_or("questions é obrigatório.")?.to_string();let gold=object.get("gold").ok_or("gold é obrigatório.")?.to_string();Ok(CreateDatasetExample{id,state,questions,gold})}
fn init_db(path: &str) -> rusqlite::Result<Connection> {
    if let Some(parent) = FsPath::new(path).parent() { std::fs::create_dir_all(parent).map_err(|_| rusqlite::Error::InvalidPath(FsPath::new(path).to_owned()))?; }
    let db = Connection::open(path)?;
    db.execute_batch("PRAGMA foreign_keys = ON; CREATE TABLE IF NOT EXISTS schema_migrations (version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);")?;
    let version:i64=db.query_row("SELECT COALESCE(MAX(version),0) FROM schema_migrations",[],|r|r.get(0))?;
    if version < 1 { db.execute_batch("
        CREATE TABLE IF NOT EXISTS folders (id INTEGER PRIMARY KEY, parent_id INTEGER REFERENCES folders(id) ON DELETE CASCADE, name TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(parent_id, name));
        CREATE TABLE IF NOT EXISTS content (id INTEGER PRIMARY KEY, folder_id INTEGER REFERENCES folders(id) ON DELETE SET NULL, kind TEXT NOT NULL CHECK(kind IN ('dataset','training')), subject TEXT NOT NULL, title TEXT NOT NULL, brief TEXT NOT NULL, markdown TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
        CREATE TABLE IF NOT EXISTS training_jobs (id INTEGER PRIMARY KEY, name TEXT NOT NULL, status TEXT NOT NULL, source_count INTEGER NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
        CREATE TABLE IF NOT EXISTS training_job_items (training_job_id INTEGER NOT NULL REFERENCES training_jobs(id) ON DELETE CASCADE, content_id INTEGER NOT NULL REFERENCES content(id), PRIMARY KEY(training_job_id, content_id));
        INSERT INTO schema_migrations(version) VALUES (1);")?; }
    if version < 2 { db.execute_batch("
        CREATE TABLE datasets (id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE, description TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
        CREATE TABLE dataset_imports (id INTEGER PRIMARY KEY, dataset_id INTEGER NOT NULL REFERENCES datasets(id) ON DELETE CASCADE, file_name TEXT NOT NULL, total_lines INTEGER NOT NULL DEFAULT 0, valid_lines INTEGER NOT NULL DEFAULT 0, invalid_lines INTEGER NOT NULL DEFAULT 0, duplicate_lines INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
        CREATE TABLE dataset_examples (id INTEGER PRIMARY KEY, dataset_id INTEGER NOT NULL REFERENCES datasets(id) ON DELETE CASCADE, import_id INTEGER REFERENCES dataset_imports(id) ON DELETE SET NULL, example_id TEXT NOT NULL, state_json TEXT NOT NULL, questions_json TEXT NOT NULL, gold_json TEXT NOT NULL, validation_status TEXT NOT NULL CHECK(validation_status IN ('valid','invalid')), validation_errors_json TEXT NOT NULL DEFAULT '[]', source TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(dataset_id,example_id));
        CREATE TABLE dataset_versions (id INTEGER PRIMARY KEY, dataset_id INTEGER NOT NULL REFERENCES datasets(id) ON DELETE RESTRICT, number INTEGER NOT NULL, example_count INTEGER NOT NULL, content_sha256 TEXT NOT NULL, contract_version TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(dataset_id,number));
        CREATE TABLE dataset_version_examples (dataset_version_id INTEGER NOT NULL REFERENCES dataset_versions(id) ON DELETE CASCADE, example_id TEXT NOT NULL, state_json TEXT NOT NULL, questions_json TEXT NOT NULL, gold_json TEXT NOT NULL, PRIMARY KEY(dataset_version_id,example_id));
        INSERT INTO schema_migrations(version) VALUES (2);")?; }
    if version < 3 { db.execute_batch("CREATE TABLE dataset_import_errors (id INTEGER PRIMARY KEY, import_id INTEGER NOT NULL REFERENCES dataset_imports(id) ON DELETE CASCADE, line_number INTEGER NOT NULL, example_id TEXT, field TEXT, reason TEXT NOT NULL); INSERT INTO schema_migrations(version) VALUES (3);")?; }
    Ok(db)
}
fn build_tree(parent: Option<i64>, folders: &[Folder]) -> Vec<FolderNode> {
    folders.iter().filter(|folder| folder.parent_id == parent).cloned().map(|folder| FolderNode { children: build_tree(Some(folder.id), folders), folder }).collect()
}

async fn health() -> &'static str { "ok\n" }
